use std::collections::BTreeMap;

use pplx_space_common_core::types::{AutoLifecyclePolicy, Email, OrgId, TemplateName, UserId};
use pplx_space_metrics::sandbox::api::SandboxApiMetricIdentity;
use pplx_space_net_common::NetworkPolicyV1;
use uuid::Uuid;

use super::*;
use crate::controllers::substrate::{
    ActorRef, CreateBootMode, CreateExecutionRequest, PooledExecutionClaim,
    PooledExecutionClaimRequest, SandboxResources, TemplateRef,
};
use pplx_space_common_core::types::SandboxId;

fn actor() -> ActorRef {
    ActorRef::new(
        UserId::from_uuid(Uuid::from_u128(1)),
        OrgId::from_uuid(Uuid::from_u128(2)),
        Email::parse("user@example.com".to_string()).unwrap(),
    )
}

/// The structural guarantee: a cold create and a warm-pool adoption built
/// from equivalent inputs resolve to byte-identical per-sandbox setup. If a
/// new setup field is added but only wired into one path's resolver, this
/// equality breaks.
fn assert_cold_matches_adoption(
    network_policy_override: Option<&NetworkPolicyV1>,
    auto_lifecycle: &AutoLifecyclePolicy,
    template_network_policy: &NetworkPolicyV1,
) {
    let actor = actor();
    let env: BTreeMap<String, String> = BTreeMap::new();
    let template = TemplateName::parse("seed").unwrap();
    let resources = SandboxResources {
        vcpu: None,
        memory_mib: None,
        disk_mib: None,
    };
    let template_ref = TemplateRef {
        template: &template,
        content_hash: Some("hash"),
        boot_mode: CreateBootMode::Fallthrough,
        runtime: "fc",
    };

    let cold = CreateExecutionRequest {
        metric_identity: SandboxApiMetricIdentity::native("create"),
        sandbox_id: SandboxId::from_uuid(Uuid::from_u128(3)),
        actor: &actor,
        template_ref: &template_ref,
        resources: &resources,
        env: &env,
        auto_lifecycle,
        network_policy_override,
        network_policy_generation: 1,
        template_network_policy,
        template_network_policy_generation: 7,
        disk_io_limits: Default::default(),
        restore_from: None,
        wait_until_ready: true,
        volume_encryption: false,
        node_pool: None,
    };

    let pooled = PooledExecutionClaimRequest {
        metric_identity: SandboxApiMetricIdentity::native("create"),
        actor: &actor,
        template: "seed",
        content_hash: Some("hash"),
        template_release_id: None,
        runtime: "fc",
        vcpu: None,
        memory_mib: None,
        env: &env,
        auto_lifecycle,
        network_policy_override,
        network_policy_generation: 1,
        template_network_policy,
        template_network_policy_generation: 7,
        volume_encryption: false,
    };
    let claim = PooledExecutionClaim {
        claim_id: Uuid::now_v7(),
        pool_slot_id: Some(Uuid::now_v7()),
        sandbox_id: SandboxId::new(),
        content_hash: "hash".to_string(),
        pod_name: "space-sbx-test-g1".to_string(),
        pod_uid: None,
        execution_generation: 1,
        pod_ip: "10.0.0.2".to_string(),
        vcpu: None,
        memory_mib: None,
        disk_mib: None,
        disk_io_limits: Default::default(),
        active_node_id: None,
        route_identity: None,
    };

    assert_eq!(
        PerSandboxSetup::from_create_request(&cold),
        PerSandboxSetup::from_claim_request(&pooled, &claim),
        "warm-pool adoption must resolve the same per-sandbox setup as a cold create"
    );
}

#[test]
fn adoption_inherits_template_network_policy_setup_like_cold() {
    let auto_lifecycle = AutoLifecyclePolicy::default();
    let template_policy = NetworkPolicyV1::deny_all();
    assert_cold_matches_adoption(None, &auto_lifecycle, &template_policy);
}

#[test]
fn adoption_applies_network_policy_override_setup_like_cold() {
    let auto_lifecycle = AutoLifecyclePolicy::default();
    let template_policy = NetworkPolicyV1::deny_all();
    let override_policy = NetworkPolicyV1::allow_all();
    assert_cold_matches_adoption(Some(&override_policy), &auto_lifecycle, &template_policy);
}

#[test]
fn setup_captures_owner_and_effective_policy() {
    let actor = actor();
    let template_policy = NetworkPolicyV1::deny_all();
    let override_policy = NetworkPolicyV1::allow_all();
    let auto_lifecycle = AutoLifecyclePolicy::default();
    let mut env = BTreeMap::new();
    env.insert("SANDBOX_TYPE".to_string(), "example-workload".to_string());
    let setup = PerSandboxSetup::resolve(
        &actor,
        EnvMap::try_from(env).unwrap(),
        &auto_lifecycle,
        Some(&override_policy),
        &template_policy,
        true,
        Default::default(),
    );
    assert!(setup.volume_encryption);
    assert_eq!(setup.sandbox_owner, actor.sandbox_owner);
    assert_eq!(setup.process_env.as_map().len(), 1);
    assert!(!format!("{setup:?}").contains("example-workload"));
    assert_eq!(setup.network_policy.effective_policy, override_policy);
    assert_eq!(
        setup.network_policy.override_policy.as_ref(),
        Some(&override_policy)
    );
    assert_eq!(setup.network_policy.authority, PolicyAuthority::Cluster);
    assert_eq!(
        setup.node_fs,
        NodeFilesystemSetup::EnsureArtifactDirPermissions
    );
}

use super::*;
use futures_util::poll;
use k8s_openapi::api::core::v1::{
    Container, ContainerPort, Node, Pod, PodCondition, PodSpec as K8sPodSpec,
    PodStatus as K8sPodStatus,
};
use kube::{api::ObjectMeta, runtime::watcher::Event};
use std::task::Poll;

fn make_pod(node: &str, ip: &str, ready: bool, app: &str) -> Pod {
    let mut labels = std::collections::BTreeMap::new();
    labels.insert("app.kubernetes.io/name".to_string(), app.to_string());
    Pod {
        metadata: ObjectMeta {
            name: Some(format!("{app}-{node}")),
            labels: Some(labels),
            ..Default::default()
        },
        spec: Some(K8sPodSpec {
            node_name: Some(node.to_string()),
            ..Default::default()
        }),
        status: Some(K8sPodStatus {
            pod_ip: Some(ip.to_string()),
            conditions: Some(vec![PodCondition {
                type_: "Ready".to_string(),
                status: if ready { "True" } else { "False" }.to_string(),
                ..Default::default()
            }]),
            ..Default::default()
        }),
    }
}

fn make_port_pod(annotation_port: Option<&str>, container_port: Option<i32>) -> Pod {
    let mut pod = make_pod("node-a", "10.0.0.1", true, "space-worker");
    if let Some(port) = annotation_port {
        pod.metadata
            .annotations
            .get_or_insert_default()
            .insert(NODE_API_PORT_ANNOTATION.to_string(), port.to_string());
    }
    if let Some(port) = container_port {
        pod.spec.as_mut().unwrap().containers = vec![Container {
            name: "node-api".to_string(),
            ports: Some(vec![ContainerPort {
                name: Some("grpc".to_string()),
                container_port: port,
                ..Default::default()
            }]),
            ..Default::default()
        }];
    }
    pod
}

fn caches_with_pods(pods: Vec<Pod>) -> K8sCaches {
    let (pod_store, mut pod_writer) = reflector::store::<Pod>();
    let (node_store, _node_writer) = reflector::store::<Node>();
    pod_writer.apply_watcher_event(&Event::Init);
    for pod in &pods {
        pod_writer.apply_watcher_event(&Event::InitApply(pod.clone()));
    }
    pod_writer.apply_watcher_event(&Event::InitDone);
    K8sCaches {
        node_api_pods: pod_store,
        nodes: node_store,
        nodes_ready: super::super::pod_reflector::ReflectorReady::always_ready(),
    }
}

#[tokio::test]
async fn startup_wait_does_not_lose_node_readiness_notification() {
    let (pod_store, mut pod_writer) = reflector::store::<Pod>();
    pod_writer.apply_watcher_event(&Event::Init);
    pod_writer.apply_watcher_event(&Event::InitDone);

    let (node_store, mut node_writer) = reflector::store::<Node>();
    let nodes_ready = super::super::pod_reflector::ReflectorReady::new();
    let nodes_ready_task = nodes_ready.clone();
    let node_store_for_ready = node_store.clone();
    tokio::spawn(async move {
        if node_store_for_ready.wait_until_ready().await.is_ok() {
            nodes_ready_task.mark_ready();
        }
    });
    tokio::task::yield_now().await;

    let caches = K8sCaches {
        node_api_pods: pod_store,
        nodes: node_store,
        nodes_ready,
    };
    let mut startup_wait = std::pin::pin!(caches.wait_until_ready());
    assert!(matches!(poll!(startup_wait.as_mut()), Poll::Pending));

    node_writer.apply_watcher_event(&Event::Init);
    node_writer.apply_watcher_event(&Event::InitDone);
    startup_wait
        .await
        .expect("startup cache wait should finish");
    tokio::task::yield_now().await;

    assert!(
        caches.nodes_ready(),
        "the durable Node readiness signal must not lose the store notification"
    );
}

#[tokio::test]
async fn startup_wait_returns_known_node_writer_failure_without_timing_out() {
    let (pod_store, mut pod_writer) = reflector::store::<Pod>();
    pod_writer.apply_watcher_event(&Event::Init);
    pod_writer.apply_watcher_event(&Event::InitDone);

    let (node_store, node_writer) = reflector::store::<Node>();
    let nodes_ready = super::super::pod_reflector::ReflectorReady::new();
    let nodes_ready_task = nodes_ready.clone();
    let node_store_for_ready = node_store.clone();
    tokio::spawn(async move {
        match node_store_for_ready.wait_until_ready().await {
            Ok(()) => nodes_ready_task.mark_ready(),
            Err(_error) => nodes_ready_task.mark_writer_dropped(),
        }
    });
    drop(node_writer);
    tokio::task::yield_now().await;

    let caches = K8sCaches {
        node_api_pods: pod_store,
        nodes: node_store,
        nodes_ready,
    };
    let result = tokio::time::timeout(Duration::from_millis(100), caches.wait_until_ready())
        .await
        .expect("a known writer failure must not wait for the startup timeout");

    assert!(matches!(result, Err(CacheReadyError::WriterDropped)));
}

#[tokio::test]
async fn startup_wait_reports_node_writer_failure_while_pods_are_pending() {
    let (pod_store, _pod_writer) = reflector::store::<Pod>();
    let (node_store, _node_writer) = reflector::store::<Node>();
    let nodes_ready = super::super::pod_reflector::ReflectorReady::new();
    nodes_ready.mark_writer_dropped();

    let caches = K8sCaches {
        node_api_pods: pod_store,
        nodes: node_store,
        nodes_ready,
    };
    let result = tokio::time::timeout(Duration::from_millis(100), caches.wait_until_ready())
        .await
        .expect("a known Node writer failure must not be hidden by pending pod readiness");

    assert!(matches!(result, Err(CacheReadyError::WriterDropped)));
}

#[test]
fn pod_is_ready_reflects_condition() {
    assert!(pod_is_ready(&make_pod(
        "n",
        "10.0.0.1",
        true,
        "space-worker"
    )));
    assert!(!pod_is_ready(&make_pod(
        "n",
        "10.0.0.1",
        false,
        "space-worker"
    )));
}

#[test]
fn ready_node_api_pod_on_picks_ready_pod_on_node() {
    let caches = caches_with_pods(vec![
        make_pod("node-a", "10.0.0.1", false, "space-worker"),
        make_pod("node-a", "10.0.0.2", true, "space-worker"),
        make_pod("node-b", "10.0.0.3", true, "space-worker"),
    ]);
    let found = caches
        .ready_node_api_pod_on("node-a", SpaceNodeRole::Worker.as_str())
        .unwrap();
    assert_eq!(pod_ip(&found), Some("10.0.0.2"));
    assert!(
        caches
            .ready_node_api_pod_on("node-z", SpaceNodeRole::Worker.as_str())
            .is_none()
    );
}

#[test]
fn ready_node_api_pod_on_disambiguates_by_role() {
    let caches = caches_with_pods(vec![
        make_pod("node-a", "10.0.0.5", true, "space-builder"),
        make_pod("node-a", "10.0.0.6", true, "space-worker"),
    ]);
    let worker = caches
        .ready_node_api_pod_on("node-a", SpaceNodeRole::Worker.as_str())
        .unwrap();
    assert_eq!(pod_ip(&worker), Some("10.0.0.6"));
    let builder = caches
        .ready_node_api_pod_on("node-a", SpaceNodeRole::Builder.as_str())
        .unwrap();
    assert_eq!(pod_ip(&builder), Some("10.0.0.5"));
}

#[test]
fn ready_node_api_pod_on_accepts_canary_worker_identity() {
    let caches = caches_with_pods(vec![make_pod(
        "node-a",
        "10.0.0.7",
        true,
        "space-worker-canary",
    )]);

    let worker = caches
        .ready_node_api_pod_on("node-a", SpaceNodeRole::Worker.as_str())
        .unwrap();

    assert_eq!(pod_ip(&worker), Some("10.0.0.7"));
}

#[test]
fn canary_worker_app_name_maps_to_worker_role() {
    let role = role_from_app_name("space-worker-canary");

    assert_eq!(role, Some(SpaceNodeRole::Worker.as_str()));
}

#[test]
fn pod_node_api_port_prefers_annotation_over_legacy_container_port() {
    let pod = make_port_pod(Some("9801"), Some(9800));
    assert_eq!(pod_node_api_port(&pod), Some(9801));
}

#[test]
fn pod_node_api_port_falls_back_to_legacy_container_port() {
    let pod = make_port_pod(None, Some(9802));
    assert_eq!(pod_node_api_port(&pod), Some(9802));
}

#[test]
fn pod_node_api_port_ignores_invalid_values() {
    assert_eq!(
        pod_node_api_port(&make_port_pod(Some("invalid"), None)),
        None
    );
    assert_eq!(pod_node_api_port(&make_port_pod(Some("70000"), None)), None);
}

//! Kubernetes node inventory writes only Kubernetes (`'k8s'`) node rows.
//!
//! Each test pairs a Kubernetes node with an otherwise identical node whose
//! `managed_by` is `'space'`, so only the `managed_by` predicates decide
//! which one the inventory statements act on.

use pplx_space_common_core::types::NodeId;
use tokio_util::task::AbortOnDropHandle;

use super::*;

async fn relabel_node(pool: &PgPool, node_id: NodeId, managed_by: &str) -> TestResult {
    sqlx::query(sql!("UPDATE nodes SET managed_by = $2 WHERE id = $1"))
        .bind(node_id)
        .bind(managed_by)
        .execute(pool)
        .await?;
    Ok(())
}

/// Registers a ready Kubernetes worker whose heartbeat and Kubernetes
/// registration are `age` old, so a membership snapshot that omits it may
/// demote it.
async fn insert_stale_ready_k8s_node(
    fixture: &PostgresStore,
    node_id: NodeId,
    node_name: &str,
    age: Duration,
) -> TestResult {
    fixture
        .store
        .persist_k8s_node_inventory(
            node_name,
            &format!("uid-{node_id}"),
            node_id,
            NodeRole::Worker,
            Some("10.0.0.60"),
            NodeStateWrite::Manage(NodeLifecycleState::Ready),
        )
        .await?;
    let age_secs = i64::try_from(age.as_secs())?;
    sqlx::query(sql!(
        "UPDATE nodes SET last_heartbeat = NOW() - ($2 * INTERVAL '1 second') WHERE id = $1"
    ))
    .bind(node_id)
    .bind(age_secs)
    .execute(&fixture.pool)
    .await?;
    sqlx::query(sql!(
        "UPDATE node_k8s SET updated_at = NOW() - ($2 * INTERVAL '1 second') WHERE node_id = $1"
    ))
    .bind(node_id)
    .bind(age_secs)
    .execute(&fixture.pool)
    .await?;
    Ok(())
}

async fn node_state(pool: &PgPool, node_id: NodeId) -> TestResult<(String, String)> {
    Ok(
        sqlx::query_as(sql!("SELECT managed_by, state FROM nodes WHERE id = $1"))
            .bind(node_id)
            .fetch_one(pool)
            .await?,
    )
}

/// A Direct node that still has a `node_k8s` row is never a demotion
/// candidate. With one demotion per tick, the older Direct node would
/// otherwise take the slot and the Kubernetes node would stay `ready`.
#[tokio::test(flavor = "current_thread")]
async fn demotion_selects_only_kubernetes_nodes() -> TestResult {
    let fixture = postgres_store().await?;
    let direct = NodeId::new();
    let kubernetes = NodeId::new();
    let direct_name = format!("space-test-direct-{}", direct.as_uuid().simple());
    let kubernetes_name = format!("space-test-k8s-{}", kubernetes.as_uuid().simple());
    insert_stale_ready_k8s_node(&fixture, direct, &direct_name, Duration::from_secs(7200)).await?;
    insert_stale_ready_k8s_node(
        &fixture,
        kubernetes,
        &kubernetes_name,
        Duration::from_secs(3600),
    )
    .await?;
    relabel_node(&fixture.pool, direct, "space").await?;

    let demoted = fixture
        .store
        .demote_unobserved_k8s_nodes(
            &["space-test-observed".to_string()],
            Duration::from_secs(60),
            1,
        )
        .await?;

    assert_eq!(demoted, vec![kubernetes_name]);
    assert_eq!(
        node_state(&fixture.pool, kubernetes).await?,
        ("k8s".to_string(), "registered".to_string())
    );
    assert_eq!(
        node_state(&fixture.pool, direct).await?,
        ("space".to_string(), "ready".to_string())
    );
    Ok(())
}

/// The demotion UPDATE re-checks `managed_by` on the row it locks. A writer
/// holds the candidate's row lock with an uncommitted relabel; the demotion's
/// candidate scan sees the committed `'k8s'` row, its UPDATE waits on the
/// lock, then re-evaluates the committed row. A relabel to `'space'` is
/// skipped; a write that keeps `'k8s'` is demoted.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn demotion_rechecks_the_substrate_of_the_row_it_locks() -> TestResult {
    for (relabel_to, expected) in [("space", None), ("k8s", Some("registered"))] {
        let fixture = postgres_store_with_max_connections(4).await?;
        let node_id = NodeId::new();
        let node_name = format!("space-test-relabel-{}", node_id.as_uuid().simple());
        insert_stale_ready_k8s_node(&fixture, node_id, &node_name, Duration::from_secs(3600))
            .await?;

        let mut writer = fixture.pool.begin().await?;
        let writer_pid: i32 = sqlx::query_scalar(sql!("SELECT pg_backend_pid()"))
            .fetch_one(&mut *writer)
            .await?;
        sqlx::query(sql!("UPDATE nodes SET managed_by = $2 WHERE id = $1"))
            .bind(node_id)
            .bind(relabel_to)
            .execute(&mut *writer)
            .await?;

        // Aborted if the test fails before joining it.
        let store = fixture.store.clone();
        let mut demotion = AbortOnDropHandle::new(tokio::spawn(async move {
            store
                .demote_unobserved_k8s_nodes(
                    &["space-test-observed".to_string()],
                    Duration::from_secs(60),
                    10,
                )
                .await
        }));
        // Commit only once the demotion statement is waiting on this
        // writer's row lock, not on any other lock.
        let waits_on_writer = async {
            loop {
                let blocked: bool = sqlx::query_scalar(sql!(
                    "SELECT EXISTS (
                         SELECT 1
                           FROM pg_stat_activity
                          WHERE datname = current_database()
                            AND wait_event_type = 'Lock'
                            AND $1 = ANY(pg_blocking_pids(pid))
                            AND query LIKE '%WITH candidates AS MATERIALIZED%'
                     )"
                ))
                .bind(writer_pid)
                .fetch_one(&fixture.pool)
                .await?;
                if blocked {
                    return Ok::<(), sqlx::Error>(());
                }
                tokio::time::sleep(Duration::from_millis(10)).await;
            }
        };
        // Both arms are bounded: the demotion must neither finish before it
        // waits on the writer nor fail to reach that wait.
        tokio::time::timeout(Duration::from_secs(5), async {
            tokio::select! {
                finished = &mut demotion => Err(format!(
                    "relabel to {relabel_to}: the demotion finished without waiting on the writer: \
                     {finished:?}"
                )),
                waited = waits_on_writer => waited.map_err(|error| error.to_string()),
            }
        })
        .await
        .map_err(|_| {
            format!("relabel to {relabel_to}: the demotion never waited on the writer")
        })??;
        writer.commit().await?;
        let demoted = tokio::time::timeout(Duration::from_secs(5), demotion).await???;

        let (managed_by, state) = node_state(&fixture.pool, node_id).await?;
        assert_eq!(managed_by, relabel_to);
        match expected {
            Some(expected_state) => {
                assert_eq!(demoted, vec![node_name], "relabel to {relabel_to}");
                assert_eq!(state, expected_state, "relabel to {relabel_to}");
            }
            None => {
                assert!(demoted.is_empty(), "relabel to {relabel_to}: {demoted:?}");
                assert_eq!(state, "ready", "relabel to {relabel_to}");
            }
        }
    }
    Ok(())
}

/// The inventory upsert writes new rows as Kubernetes nodes, updates an
/// existing Kubernetes row, and refuses a Direct row at the same id, leaving
/// it unchanged.
#[tokio::test(flavor = "current_thread")]
async fn inventory_upsert_writes_only_kubernetes_rows() -> TestResult {
    let fixture = postgres_store().await?;
    let fresh = NodeId::new();
    let kubernetes = NodeId::new();
    let direct = NodeId::new();
    for (node_id, managed_by) in [(kubernetes, "k8s"), (direct, "space")] {
        sqlx::query(sql!(
            "INSERT INTO nodes (id, address, role, managed_by, state)
             VALUES ($1, '10.0.0.61'::INET, 'worker', $2, 'registered')"
        ))
        .bind(node_id)
        .bind(managed_by)
        .execute(&fixture.pool)
        .await?;
    }
    let persist = |node_id: NodeId| {
        let store = fixture.store.clone();
        async move {
            store
                .persist_k8s_node_inventory(
                    &format!("space-test-upsert-{}", node_id.as_uuid().simple()),
                    &format!("uid-{node_id}"),
                    node_id,
                    NodeRole::Worker,
                    Some("10.0.0.62"),
                    NodeStateWrite::Manage(NodeLifecycleState::Ready),
                )
                .await
        }
    };
    let row = |node_id: NodeId| {
        let pool = fixture.pool.clone();
        async move {
            sqlx::query_as::<_, (String, String, String)>(sql!(
                "SELECT managed_by, host(address), state FROM nodes WHERE id = $1"
            ))
            .bind(node_id)
            .fetch_one(&pool)
            .await
        }
    };
    let k8s_registrations = |node_id: NodeId| {
        let pool = fixture.pool.clone();
        async move {
            sqlx::query_scalar::<_, i64>(sql!("SELECT COUNT(*) FROM node_k8s WHERE node_id = $1"))
                .bind(node_id)
                .fetch_one(&pool)
                .await
        }
    };

    assert!(persist(fresh).await?);
    assert_eq!(
        row(fresh).await?,
        ("k8s".into(), "10.0.0.62".into(), "ready".into())
    );

    assert!(persist(kubernetes).await?);
    assert_eq!(
        row(kubernetes).await?,
        ("k8s".into(), "10.0.0.62".into(), "ready".into())
    );

    let refused = persist(direct).await;
    assert!(
        matches!(refused, Err(SubstrateError::Failed { .. })),
        "{refused:?}"
    );
    assert_eq!(
        row(direct).await?,
        ("space".into(), "10.0.0.61".into(), "registered".into())
    );
    assert_eq!(k8s_registrations(direct).await?, 0);
    Ok(())
}

//! Postgres behaviors for the disk-only restore-source selector an evacuated
//! `stopped` sandbox resolves through
//! (`K8sStore::selected_stopped_restore_storage_uri`).
//!
//! A sibling module rather than more lines in the parent: the parent is
//! already far past the repository's file-size guidance, and these behaviors
//! share nothing with it but the fixture. They take `&PostgresStore` and are
//! driven from `k8s_store_postgres_behaviors`, so they run against the same
//! database and mint no second container.

use pplx_space_common_core::types::{LocalArtifactId, SandboxId, SnapshotId};

use super::*;
use pplx_space_db_test_fixtures::SEED_ORG_ID;
use pplx_space_sandbox_portability::snapshot_is_live_restore_source;

/// Register a `disk` snapshot with a usable storage location, mirroring what
/// `BeginArtifactBackup(ArtifactKind::Disk)` plus a `READY`
/// `FinalizeArtifactBackup` leave in the catalog. `local_artifact_id` carries
/// the artifact identity the node minted; `None` models a row that predates the
/// identity columns.
///
/// `age_seconds` counts *backwards* from `NOW()`, so a larger value is older.
/// Note that the sibling `insert_ready_full_snapshot_relative_to_lifecycle`
/// takes an offset *forward* from `lifecycle_changed_at`, where larger is
/// newer — the same argument position runs in opposite directions between the
/// two helpers.
///
/// The shared `pplx_space_db_test_fixtures::publish_ready_disk_artifact` covers
/// the "artifact is durable" shape; this one exists because these behaviors
/// have to vary `state`, the timestamp, and the identity *independently of the
/// pin* — which is the whole subject matter.
async fn insert_disk_snapshot(
    pool: &PgPool,
    sandbox_id: SandboxId,
    uri: &str,
    state: &str,
    age_seconds: i32,
    local_artifact_id: Option<LocalArtifactId>,
) -> TestResult<SnapshotId> {
    insert_disk_snapshot_with_id(
        pool,
        sandbox_id,
        SnapshotId::new(),
        uri,
        state,
        age_seconds,
        local_artifact_id,
    )
    .await
}

/// As [`insert_disk_snapshot`], with the `snapshots.id` chosen by the caller.
/// Only the tiebreak assertion needs that: it seeds two rows at one timestamp
/// and has to know which id is the larger.
#[allow(clippy::too_many_arguments)]
async fn insert_disk_snapshot_with_id(
    pool: &PgPool,
    sandbox_id: SandboxId,
    snapshot_id: SnapshotId,
    uri: &str,
    state: &str,
    age_seconds: i32,
    local_artifact_id: Option<LocalArtifactId>,
) -> TestResult<SnapshotId> {
    let artifact_kind = local_artifact_id.map(|_| "disk");
    let artifact_origin = local_artifact_id.map(|_| "stop");
    sqlx::query(sql!(
        "INSERT INTO snapshots
             (id, sandbox_id, type, state, timestamp, org_id,
              local_artifact_id, artifact_kind, artifact_origin)
         VALUES ($1, $2, 'disk', $3,
                 NOW() - ($4 * INTERVAL '1 second'),
                 $5, $6, $7, $8)"
    ))
    .bind(snapshot_id)
    .bind(sandbox_id)
    .bind(state)
    .bind(age_seconds)
    .bind(SEED_ORG_ID)
    .bind(local_artifact_id)
    .bind(artifact_kind)
    .bind(artifact_origin)
    .execute(pool)
    .await?;
    sqlx::query(sql!(
        "INSERT INTO snapshot_storage_locations
             (snapshot_id, storage_connection_string, org_id)
         VALUES ($1, $2, $3)"
    ))
    .bind(snapshot_id)
    .bind(uri)
    .bind(SEED_ORG_ID)
    .execute(pool)
    .await?;
    Ok(snapshot_id)
}

async fn set_artifact_pin(
    pool: &PgPool,
    sandbox_id: SandboxId,
    artifact_id: Option<LocalArtifactId>,
    kind: Option<&str>,
) -> TestResult {
    // Origin tracks kind: `publish_stopped_artifact` mints `disk`/`stop`, and
    // the suspend writers mint `full`/`suspend`. Deriving it here keeps the
    // invalid `(Some(id), None)` combination out of every call site.
    let origin = kind.map(|kind| if kind == "disk" { "stop" } else { "suspend" });
    sqlx::query(sql!(
        "UPDATE sandboxes
            SET current_local_artifact_id = $2,
                current_local_artifact_kind = $3,
                current_local_artifact_origin = $4
          WHERE id = $1"
    ))
    .bind(sandbox_id)
    .bind(artifact_id)
    .bind(kind)
    .bind(origin)
    .execute(pool)
    .await?;
    Ok(())
}

async fn set_lifecycle(pool: &PgPool, sandbox_id: SandboxId, lifecycle: &str) -> TestResult {
    sqlx::query(sql!("UPDATE sandboxes SET lifecycle = $2 WHERE id = $1"))
        .bind(sandbox_id)
        .bind(lifecycle)
        .execute(pool)
        .await?;
    Ok(())
}

async fn selected_stopped_uri(
    fixture: &PostgresStore,
    sandbox_id: SandboxId,
) -> TestResult<Option<String>> {
    let sandbox = fixture.store.require_sandbox(sandbox_id).await?;
    Ok(fixture
        .store
        .selected_stopped_restore_storage_uri(&sandbox)
        .await?)
}

/// The operator-visible property: a stopped sandbox is restartable off its
/// node exactly when the bytes that *are* its current rootfs are durable and
/// reachable. Not "an upload for it started", not "some disk image of it
/// exists" — the pinned one, finished, with a live location.
///
/// Every negative below is one mutation away from the positive, so none of
/// them can pass because the fixture was incomplete.
pub(super) async fn stopped_disk_selector_requires_the_pinned_ready_disk_artifact(
    fixture: &PostgresStore,
) -> TestResult {
    let sandbox_id = SandboxId::new();
    let artifact_id = LocalArtifactId::new();
    let uri = "s3://space-test/stopped-disk-evacuated?region=us-east-1";
    insert_sandbox(&fixture.pool, sandbox_id, "stopped").await?;
    set_artifact_pin(&fixture.pool, sandbox_id, Some(artifact_id), Some("disk")).await?;
    let snapshot_id = insert_disk_snapshot(
        &fixture.pool,
        sandbox_id,
        uri,
        "creating",
        60,
        Some(artifact_id),
    )
    .await?;

    assert_eq!(
        selected_stopped_uri(fixture, sandbox_id).await?,
        None,
        "an in-flight disk upload is not yet a restore source"
    );

    sqlx::query(sql!("UPDATE snapshots SET state = 'ready' WHERE id = $1"))
        .bind(snapshot_id)
        .execute(&fixture.pool)
        .await?;
    assert_eq!(
        selected_stopped_uri(fixture, sandbox_id).await?.as_deref(),
        Some(uri),
        "a ready pinned disk artifact with a live location is the restore source"
    );

    sqlx::query(sql!(
        "UPDATE snapshot_storage_locations SET orphaned_at = NOW() WHERE snapshot_id = $1"
    ))
    .bind(snapshot_id)
    .execute(&fixture.pool)
    .await?;
    assert_eq!(
        selected_stopped_uri(fixture, sandbox_id).await?,
        None,
        "an orphaned location must not be handed to a restore"
    );
    sqlx::query(sql!(
        "UPDATE snapshot_storage_locations SET orphaned_at = NULL WHERE snapshot_id = $1"
    ))
    .bind(snapshot_id)
    .execute(&fixture.pool)
    .await?;

    // The lifecycle filter is load-bearing, not decoration. `suspended` /
    // `restoring` belong to the suspend selector, and for `started` / `paused`
    // the live copy on the source node is canonical — the reason the
    // portability module gives for treating any published snapshot of them as
    // stale.
    for foreign_lifecycle in ["suspended", "restoring", "started", "paused"] {
        set_lifecycle(&fixture.pool, sandbox_id, foreign_lifecycle).await?;
        assert_eq!(
            selected_stopped_uri(fixture, sandbox_id).await?,
            None,
            "{foreign_lifecycle} must not resolve through the stopped disk selector"
        );
    }
    set_lifecycle(&fixture.pool, sandbox_id, "stopped").await?;

    // No markerless legacy branch. A sandbox that lost its pin, and a
    // snapshot that carries no artifact identity, are each unselectable —
    // there is no timestamp rule that would substitute for the identity.
    set_artifact_pin(&fixture.pool, sandbox_id, None, None).await?;
    assert_eq!(
        selected_stopped_uri(fixture, sandbox_id).await?,
        None,
        "a sandbox with no artifact pin has nothing to resolve the artifact by"
    );
    set_artifact_pin(&fixture.pool, sandbox_id, Some(artifact_id), Some("disk")).await?;
    sqlx::query(sql!(
        "UPDATE snapshots
            SET local_artifact_id = NULL, artifact_kind = NULL, artifact_origin = NULL
          WHERE id = $1"
    ))
    .bind(snapshot_id)
    .execute(&fixture.pool)
    .await?;
    assert_eq!(
        selected_stopped_uri(fixture, sandbox_id).await?,
        None,
        "a markerless disk snapshot is not proof it holds this sandbox's current rootfs"
    );
    sqlx::query(sql!(
        "UPDATE snapshots
            SET local_artifact_id = $2, artifact_kind = 'disk', artifact_origin = 'stop'
          WHERE id = $1"
    ))
    .bind(snapshot_id)
    .bind(artifact_id)
    .execute(&fixture.pool)
    .await?;

    // Identity, not freshness. Re-placement bumps `placement_changed_at`,
    // which is what makes a *suspend* snapshot stale; the evacuated rootfs is
    // the same bytes regardless of where the sandbox is placed next.
    sqlx::query(sql!(
        "UPDATE sandboxes SET placement_changed_at = NOW() WHERE id = $1"
    ))
    .bind(sandbox_id)
    .execute(&fixture.pool)
    .await?;
    assert_eq!(
        selected_stopped_uri(fixture, sandbox_id).await?.as_deref(),
        Some(uri),
        "a re-placement must not strand the evacuated rootfs the pin names"
    );

    // A retried backup of one artifact mints a fresh `snapshots` row per
    // attempt under the same identity, so the pin can match several rows.
    // Newest registered location wins.
    let newer_uri = "s3://space-test/stopped-disk-retry?region=us-east-1";
    insert_disk_snapshot(
        &fixture.pool,
        sandbox_id,
        newer_uri,
        "ready",
        1,
        Some(artifact_id),
    )
    .await?;
    assert_eq!(
        selected_stopped_uri(fixture, sandbox_id).await?.as_deref(),
        Some(newer_uri),
        "the newest registered copy of the pinned artifact is the one to load"
    );

    // `ORDER BY sn.timestamp DESC` alone leaves the pick unspecified when two
    // attempts of one artifact register within a single statement timestamp,
    // which is why the selector adds `sn.id DESC`. Seeding both rows at the
    // *same* instant is the only way that clause decides anything at all: with
    // the distinct timestamps used above, it is inert.
    //
    // What this establishes, precisely: inverting the clause to `sn.id ASC`
    // fails here, so the ordering is read and honored. It does **not** prove
    // the clause is load-bearing against deletion — measured, removing it
    // entirely still passes, because Postgres's unspecified order for a tie
    // happens to return the same row for this plan. No test can close that
    // gap; "unspecified" is free to coincide with the intended answer. The
    // clause is what makes the choice guaranteed rather than incidental, and
    // that guarantee is a property of the SQL, not of any fixture.
    //
    // UUIDv7 is time-ordered, so `Uuid::now_v7()` twice gives a known
    // low/high pair.
    let tie_sandbox = SandboxId::new();
    let tie_artifact_id = LocalArtifactId::new();
    let low_id = SnapshotId::new();
    let high_id = SnapshotId::new();
    assert!(low_id < high_id, "UUIDv7 must order by mint time");
    insert_sandbox(&fixture.pool, tie_sandbox, "stopped").await?;
    set_artifact_pin(
        &fixture.pool,
        tie_sandbox,
        Some(tie_artifact_id),
        Some("disk"),
    )
    .await?;
    // Inserted high-id first so insertion order cannot stand in for the
    // ordering under test.
    insert_disk_snapshot_with_id(
        &fixture.pool,
        tie_sandbox,
        high_id,
        "s3://space-test/stopped-disk-tie-high?region=us-east-1",
        "ready",
        30,
        Some(tie_artifact_id),
    )
    .await?;
    insert_disk_snapshot_with_id(
        &fixture.pool,
        tie_sandbox,
        low_id,
        "s3://space-test/stopped-disk-tie-low?region=us-east-1",
        "ready",
        30,
        Some(tie_artifact_id),
    )
    .await?;
    // Each insert commits separately, so their `NOW()` values differ by
    // microseconds — enough for `timestamp DESC` to decide and leave the
    // tiebreak untested. Collapse them onto one instant explicitly; the guard
    // below is what caught this when the fixture relied on `NOW()`.
    sqlx::query(sql!(
        "UPDATE snapshots
            SET timestamp = (SELECT MIN(timestamp) FROM snapshots WHERE sandbox_id = $1)
          WHERE sandbox_id = $1"
    ))
    .bind(tie_sandbox)
    .execute(&fixture.pool)
    .await?;
    let tied: (i64,) = sqlx::query_as(sql!(
        "SELECT COUNT(DISTINCT timestamp) FROM snapshots WHERE sandbox_id = $1"
    ))
    .bind(tie_sandbox)
    .fetch_one(&fixture.pool)
    .await?;
    assert_eq!(
        tied.0, 1,
        "the two rows must share one timestamp, or this asserts the timestamp \
         ordering again rather than the tiebreak"
    );
    assert_eq!(
        selected_stopped_uri(fixture, tie_sandbox).await?.as_deref(),
        Some("s3://space-test/stopped-disk-tie-high?region=us-east-1"),
        "on a timestamp tie the higher snapshot id must win, deterministically"
    );

    Ok(())
}

/// The two exclusions the suspend selector could not express, from the other
/// side: a `full` artifact carries VM memory a stopped sandbox does not have,
/// and a disk image belonging to some *other* artifact of the same sandbox is
/// not its current rootfs.
pub(super) async fn stopped_disk_selector_ignores_a_full_artifact_and_a_foreign_disk_artifact(
    fixture: &PostgresStore,
) -> TestResult {
    // Only a `full` artifact: a suspended-shaped catalog on a stopped row.
    // Everything else about it selects — the pin matches the snapshot's
    // identity, the row is ready, its location is live — so `sn.type` is the
    // single conjunct standing between this fixture and a hit.
    let full_only = SandboxId::new();
    let full_artifact_id = LocalArtifactId::new();
    insert_sandbox(&fixture.pool, full_only, "stopped").await?;
    set_artifact_pin(
        &fixture.pool,
        full_only,
        Some(full_artifact_id),
        Some("full"),
    )
    .await?;
    let full_snapshot_id = insert_ready_full_snapshot_relative_to_lifecycle(
        &fixture.pool,
        full_only,
        "s3://space-test/stopped-with-full-artifact?region=us-east-1",
        1,
        Some(full_artifact_id),
    )
    .await?;
    assert_eq!(
        selected_stopped_uri(fixture, full_only).await?,
        None,
        "a full artifact cannot restore a sandbox that has no VM memory to restore"
    );

    // Move that one conjunct and nothing else. `artifact_kind` stays `full` on
    // both sides, so the pin still matches; only `snapshots.type` changes.
    // Production never writes this combination — `BeginArtifactBackup` derives
    // `type` from `artifact_kind` — and that is the point: the mutation
    // isolates the filter under test instead of modelling a real row, which is
    // what makes the `None` above attributable to `sn.type` alone.
    sqlx::query(sql!("UPDATE snapshots SET type = 'disk' WHERE id = $1"))
        .bind(full_snapshot_id)
        .execute(&fixture.pool)
        .await?;
    assert_eq!(
        selected_stopped_uri(fixture, full_only).await?.as_deref(),
        Some("s3://space-test/stopped-with-full-artifact?region=us-east-1"),
        "flipping only the snapshot kind must make the same row selectable, or the \
         assertion above proved something other than the kind filter"
    );

    // A disk artifact of this sandbox that the pin has moved past — the shape
    // a superseded stop artifact and a user-taken disk snapshot both leave.
    // The selector rejects it on the pin alone, never on `artifact_origin`, so
    // one rule covers both and loading stale bytes needs no origin allowlist
    // to prevent.
    let foreign = SandboxId::new();
    let pinned_artifact_id = Uuid::now_v7();
    let foreign_artifact_id = LocalArtifactId::new();
    let foreign_uri = "s3://space-test/stopped-foreign-disk?region=us-east-1";
    insert_sandbox(&fixture.pool, foreign, "stopped").await?;
    set_artifact_pin(
        &fixture.pool,
        foreign,
        Some(LocalArtifactId::from_uuid(pinned_artifact_id)),
        Some("disk"),
    )
    .await?;
    insert_disk_snapshot(
        &fixture.pool,
        foreign,
        foreign_uri,
        "ready",
        1,
        Some(foreign_artifact_id),
    )
    .await?;
    assert_eq!(
        selected_stopped_uri(fixture, foreign).await?,
        None,
        "a disk artifact the sandbox does not pin is not its current rootfs"
    );
    set_artifact_pin(
        &fixture.pool,
        foreign,
        Some(foreign_artifact_id),
        Some("disk"),
    )
    .await?;
    assert_eq!(
        selected_stopped_uri(fixture, foreign).await?.as_deref(),
        Some(foreign_uri),
        "moving the pin onto that artifact is what makes it selectable"
    );

    Ok(())
}

/// The selector and the retention sweeper's never-prune-a-live-restore-source
/// guard agree on which row is the live restore source, because both are built
/// from `snapshot_is_current_local_artifact`.
///
/// Read what this does and does not establish. It evaluates the **guard
/// expression** against the row the selector picked; it does not exercise
/// `list_candidates` or `claim_prune`, and it is not what makes a disk row
/// unprunable today — those two filter `type = 'full'`, so a disk row is
/// outside the candidate set before the guard is reached. What this pins is
/// the agreement itself, which is what keeps the sweep safe if that `'full'`
/// narrowing is ever lifted.
///
/// The second assertion is the non-vacuity control: a guard that answered TRUE
/// for every row would satisfy the first one on its own.
pub(super) async fn stopped_disk_selector_agrees_with_the_retention_never_prune_guard(
    fixture: &PostgresStore,
) -> TestResult {
    let sandbox_id = SandboxId::new();
    let pinned_artifact_id = LocalArtifactId::new();
    let stale_artifact_id = LocalArtifactId::new();
    let pinned_uri = "s3://space-test/stopped-guard-pinned?region=us-east-1";
    let stale_uri = "s3://space-test/stopped-guard-stale?region=us-east-1";
    insert_sandbox(&fixture.pool, sandbox_id, "stopped").await?;
    set_artifact_pin(
        &fixture.pool,
        sandbox_id,
        Some(pinned_artifact_id),
        Some("disk"),
    )
    .await?;
    // The stale row is *newer*, so ordering alone would pick it. Only the pin
    // separates them, which is exactly the agreement under test.
    let pinned_snapshot_id = insert_disk_snapshot(
        &fixture.pool,
        sandbox_id,
        pinned_uri,
        "ready",
        60,
        Some(pinned_artifact_id),
    )
    .await?;
    let stale_snapshot_id = insert_disk_snapshot(
        &fixture.pool,
        sandbox_id,
        stale_uri,
        "ready",
        1,
        Some(stale_artifact_id),
    )
    .await?;

    assert_eq!(
        selected_stopped_uri(fixture, sandbox_id).await?.as_deref(),
        Some(pinned_uri),
        "the pin, not the timestamp, decides which disk artifact restore loads"
    );

    let guard = snapshot_is_live_restore_source("s", "sn");
    let guard_query = format!(
        "SELECT {guard}
           FROM sandboxes s
           JOIN snapshots sn ON sn.sandbox_id = s.id
          WHERE s.id = $1
            AND sn.id = $2"
    );
    let guards_pinned: bool = sqlx::query_scalar(sqlx::AssertSqlSafe(sql!(guard_query.as_str())))
        .bind(sandbox_id)
        .bind(pinned_snapshot_id)
        .fetch_one(&fixture.pool)
        .await?;
    assert!(
        guards_pinned,
        "the retention guard must shield the disk row the stopped selector loads"
    );
    let guards_stale: bool = sqlx::query_scalar(sqlx::AssertSqlSafe(sql!(guard_query.as_str())))
        .bind(sandbox_id)
        .bind(stale_snapshot_id)
        .fetch_one(&fixture.pool)
        .await?;
    assert!(
        !guards_stale,
        "the guard must not shield every disk row, or agreeing with it proves nothing"
    );

    Ok(())
}

